    void scanDynamic(URI seed,int max,int delay,java.util.concurrent.atomic.AtomicBoolean stop)throws Exception{ArrayDeque<URI> queue=new ArrayDeque<>();Set<URI> visited=new HashSet<>();queue.add(seed);while(!queue.isEmpty()&&visited.size()<max&&!stop.get()){URI uri=queue.removeFirst();if(!WorkbenchCore.sameOrigin(seed,uri)||!policy.allows(uri)||!visited.add(uri))continue;Map<String,Object> dom=browser.render(uri,instrumentDom.isSelected());var request=WorkbenchCore.get(uri);var reply=VulnApp.perform(request,uri);SwingUtilities.invokeLater(()->app.addExchange(request,uri,reply,0,"JS Scanner"));for(Object item:(List<?>)dom.getOrDefault("links",List.of()))try{URI link=URI.create(item.toString());if(WorkbenchCore.sameOrigin(seed,link)&&policy.allows(link)&&queue.size()<200)queue.add(link);}catch(Exception ignored){}if(delay>0)Thread.sleep(delay);}app.log("JavaScript crawl completed: "+visited.size()+" pages; same-origin resources only");}
