    void restore(Map<String,String> s){include.setText(s.getOrDefault("scopeInclude",""));exclude.setText(s.getOrDefault("scopeExclude",""));scopeOn.setSelected(Boolean.parseBoolean(s.getOrDefault("scopeOn","false")));policy.configureScope(scopeOn.isSelected(),include.getText(),exclude.getText());ruleSpec.setText(s.getOrDefault("rules",""));policy.rules(ruleSpec.getText());rulesOn.setSelected(Boolean.parseBoolean(s.getOrDefault("rulesOn","false")));policy.matchRules=rulesOn.isSelected();cookieOn.setSelected(Boolean.parseBoolean(s.getOrDefault("cookieOn","false")));policy.cookieJar=cookieOn.isSelected();protocol.setSelectedItem(s.getOrDefault("protocol","HTTP/1.1"));policy.protocol=protocol.getSelectedItem().toString();script.setText(s.getOrDefault("script",script.getText()));pipeline.setText(s.getOrDefault("pipeline",pipeline.getText()));sessionOrigin.setText(s.getOrDefault("sessionOrigin",sessionOrigin.getText()));sessionHeader.setText(s.getOrDefault("sessionHeader",""));loginRequest.setText(s.getOrDefault("loginRequest",""));tokenRegex.setText(s.getOrDefault("tokenRegex",""));tokenHeader.setText(s.getOrDefault("tokenHeader","Authorization"));notes.setRowCount(0);if(s.containsKey("organizer"))for(Object row:(List<?>)Json.parse(s.get("organizer")))notes.addRow(((List<?>)row).toArray());if(s.containsKey("repeaterTabs"))repeater.restore(s.get("repeaterTabs"));autosave.setSelected(Boolean.parseBoolean(s.getOrDefault("autosave","true")));if(s.containsKey("preferences"))WorkspaceState.restore(app,s.get("preferences"));if(s.containsKey("sessions"))WorkspaceState.sessions(policy,s.get("sessions"));}
    void saveRecovery(){if(!autosave.isSelected()||app.entries.isEmpty())return;if(!saving.compareAndSet(false,true))return;Map<String,String> state=app.advanced.state();ProjectStore.Project snapshot=new ProjectStore.Project(List.copyOf(app.entries),state);app.workers.submit(()->{try{Files.createDirectories(dataDir);Path file=dataDir.resolve("recovery.vulnproject");if(Files.exists(file))Files.copy(file,dataDir.resolve("previous.vulnproject"),StandardCopyOption.REPLACE_EXISTING);ProjectStore.write(file,snapshot);app.log("Recovery snapshot saved");}catch(Exception ex){app.error(ex);}finally{saving.set(false);}});}
    void offerRecovery(){if(Files.isRegularFile(dataDir.resolve("recovery.vulnproject"))&&JOptionPane.showConfirmDialog(app,"Uma sessão salva automaticamente está disponível. Restaurar?","VULN · Recuperação",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)recover();}
    void recover(){if(app.proxy.running()){app.log("Stop Proxy before recovering");return;}app.workers.submit(()->{try{ProjectStore.Project p;try{p=ProjectStore.read(dataDir.resolve("recovery.vulnproject"));}catch(Exception ex){p=ProjectStore.read(dataDir.resolve("previous.vulnproject"));}ProjectStore.Project project=p;SwingUtilities.invokeLater(()->app.advanced.restore(project));}catch(Exception ex){app.error(ex);}});}
